// ---------------------------------------------------------------- helpers

/// `Contact::class`, as `fileable_type`.
const CONTACT_MORPH: &str = "App\\Models\\Contact";

fn ts(t: Option<Timestamp>) -> Timestamp {
    t.unwrap_or_else(crate::db::now)
}

/// `Carbon::now()` (UTC).
fn now() -> NaiveDateTime {
    crate::db::now().0
}

/// `Carbon::now($user->timezone)`'s date; UTC when the timezone is unset or unknown.
fn user_today(user: &users::Model) -> NaiveDate {
    let tz = user.timezone.as_deref().and_then(|t| t.parse::<Tz>().ok()).unwrap_or(Tz::UTC);
    Utc::now().with_timezone(&tz).date_naive()
}

fn midnight(d: NaiveDate) -> Timestamp {
    Timestamp(d.and_time(NaiveTime::MIN))
}

/// The page query of an endpoint whose generated query has signed numbers.
fn page_query(page: Option<i64>, per_page: Option<i64>) -> PageQuery {
    PageQuery {
        page: page.map(|p| Ord::max(p, 1).unsigned_abs()),
        per_page: per_page.map(|p| Ord::max(p, 1).unsigned_abs()),
    }
}

/// The year and month `offset` months after the month of `date`.
fn month_after(date: NaiveDate, offset: i32) -> (i32, u32) {
    let index = date.year() * 12 + date.month0() as i32 + offset;
    (index.div_euclid(12), index.rem_euclid(12) as u32 + 1)
}

fn last_day_of_month(year: i32, month: u32) -> NaiveDate {
    let (y, m) = month_after(NaiveDate::from_ymd_opt(year, month, 1).expect("a valid month"), 1);
    NaiveDate::from_ymd_opt(y, m, 1).expect("a valid month") - Duration::days(1)
}

