/// The hover cards of `contacts`, by contact id.
async fn cards_by_id<C: ConnectionTrait>(
    db: &C,
    contacts: Vec<contacts::Model>,
) -> ApiResult<HashMap<Uuid, ContactCard>> {
    let mut seen = HashSet::new();
    let unique: Vec<contacts::Model> = contacts.into_iter().filter(|c| seen.insert(c.id)).collect();
    Ok(ContactCard::load_many(db, unique).await?.into_iter().map(|c| (c.id, c)).collect())
}

/// Rows of `E` whose `column` is one of `ids`.
async fn rows_in<E: EntityTrait, C: ConnectionTrait, V: Into<sea_orm::Value>>(
    db: &C,
    column: E::Column,
    ids: Vec<V>,
) -> ApiResult<Vec<E::Model>> {
    if ids.is_empty() {
        return Ok(Vec::new());
    }
    Ok(E::find().filter(column.is_in(ids)).all(db).await?)
}

fn by_id<M, K: std::hash::Hash + Eq>(rows: Vec<M>, key: impl Fn(&M) -> K) -> HashMap<K, M> {
    rows.into_iter().map(|r| (key(&r), r)).collect()
}

/// The vault's contacts (`$vault->contacts`: soft-deleted ones excluded), by id.
async fn vault_contacts<C: ConnectionTrait>(db: &C, vault_id: Uuid) -> ApiResult<HashMap<Uuid, contacts::Model>> {
    Ok(contacts::Entity::live()
        .filter(contacts::Column::VaultId.eq(vault_id))
        .all(db)
        .await?
        .into_iter()
        .map(|c| (c.id, c))
        .collect())
}

/// Live contacts of the vault among `ids`, by id.
async fn contacts_in<C: ConnectionTrait>(
    db: &C,
    vault_id: Uuid,
    ids: Vec<Uuid>,
) -> ApiResult<HashMap<Uuid, contacts::Model>> {
    if ids.is_empty() {
        return Ok(HashMap::new());
    }
    Ok(contacts::Entity::live()
        .filter(contacts::Column::VaultId.eq(vault_id))
        .filter(contacts::Column::Id.is_in(ids))
        .all(db)
        .await?
        .into_iter()
        .map(|c| (c.id, c))
        .collect())
}

/// The users of `ids` with their own contact in the vault (`UserSummary`).
type UsersInVault = HashMap<Uuid, (users::Model, Option<contacts::Model>)>;

async fn users_in_vault<C: ConnectionTrait>(db: &C, vault_id: Uuid, ids: Vec<Uuid>) -> ApiResult<UsersInVault> {
    let ids: Vec<Uuid> = ids.into_iter().collect::<HashSet<_>>().into_iter().collect();
    if ids.is_empty() {
        return Ok(HashMap::new());
    }
    let users = rows_in::<users::Entity, _, _>(db, users::Column::Id, ids.clone()).await?;
    let memberships = user_vault::Entity::find()
        .filter(user_vault::Column::VaultId.eq(vault_id))
        .filter(user_vault::Column::UserId.is_in(ids))
        .all(db)
        .await?;
    let contacts = contacts_in(db, vault_id, memberships.iter().map(|m| m.contact_id).collect()).await?;
    let own: HashMap<Uuid, Uuid> = memberships.into_iter().map(|m| (m.user_id, m.contact_id)).collect();
    Ok(users
        .into_iter()
        .map(|u| {
            let contact = own.get(&u.id).and_then(|c| contacts.get(c)).cloned();
            (u.id, (u, contact))
        })
        .collect())
}

fn user_summary(users: &UsersInVault, id: Option<Uuid>) -> Option<UserSummary> {
    id.and_then(|id| users.get(&id)).map(|(u, c)| UserSummary::new(u, c.clone()))
}

