/// The vault's important dates kept by `keep` (soft-deleted ones and those
/// of deleted contacts excluded), by id, with the hover cards of their
/// contacts and the vault's date types.
struct VaultDates {
    dates: Vec<contact_important_dates::Model>,
    cards: HashMap<Uuid, ContactCard>,
    types: HashMap<Id, contact_important_date_types::Model>,
}

impl VaultDates {
    async fn load<C: ConnectionTrait>(
        db: &C,
        vault_id: Uuid,
        keep: impl Fn(&contact_important_dates::Model) -> bool,
    ) -> ApiResult<VaultDates> {
        let contacts = vault_contacts(db, vault_id).await?;
        let mut dates: Vec<contact_important_dates::Model> = rows_in::<contact_important_dates::Entity, _, _>(
            db,
            contact_important_dates::Column::ContactId,
            contacts.keys().copied().collect(),
        )
        .await?
        .into_iter()
        .filter(|d| d.deleted_at.is_none() && keep(d))
        .collect();
        dates.sort_by_key(|d| d.id);
        let wanted: HashSet<Uuid> = dates.iter().map(|d| d.contact_id).collect();
        let cards = cards_by_id(db, contacts.into_values().filter(|c| wanted.contains(&c.id)).collect()).await?;
        let types = by_id(
            contact_important_date_types::Entity::find()
                .filter(contact_important_date_types::Column::VaultId.eq(vault_id))
                .all(db)
                .await?,
            |t| t.id,
        );
        Ok(VaultDates { dates, cards, types })
    }

    fn view(&self, d: &contact_important_dates::Model, today: NaiveDate) -> Option<CalendarImportantDate> {
        Some(CalendarImportantDate {
            day: d.day.map(i64::from),
            month: d.month.map(i64::from),
            year: d.year.map(i64::from),
            id: d.id,
            contact_id: d.contact_id,
            label: d.label.clone(),
            contact_important_date_type: d
                .contact_important_date_type_id
                .and_then(|t| self.types.get(&t))
                .map(date_type),
            age: age(d.day, d.month, d.year, today),
            created_at: ts(d.created_at),
            updated_at: ts(d.updated_at),
            contact: copy_card(self.cards.get(&d.contact_id)?),
        })
    }
}

/// `VaultCalendarIndexViewHelper::buildMonth` / `getDayInformation` for
/// `days` (consecutive dates, each with whether it is in the shown month).
async fn calendar_days(
    state: &AppState,
    access: &access::VaultAccess,
    user: &users::Model,
    days: Vec<(NaiveDate, bool)>,
) -> ApiResult<Vec<CalendarDay>> {
    let db = &state.db;
    let vault_id = access.vault.id;
    let (Some(first), Some(last)) = (days.first().map(|d| d.0), days.last().map(|d| d.0)) else {
        return Ok(Vec::new());
    };
    let (start, end) = (midnight(first), midnight(last + Duration::days(1)));
    let wanted: HashSet<(i32, i32)> = days.iter().map(|(d, _)| (d.month() as i32, d.day() as i32)).collect();
    let dates = VaultDates::load(
        db,
        vault_id,
        |d| matches!((d.month, d.day), (Some(m), Some(day)) if wanted.contains(&(m, day))),
    )
    .await?;

    let parameters = mood_parameters(db, vault_id).await?;
    let mut moods: HashMap<NaiveDate, Vec<MoodTrackingEvent>> = HashMap::new();
    for e in mood_tracking_events::Entity::find()
        .filter(mood_tracking_events::Column::ContactId.eq(access.membership.contact_id))
        .filter(mood_tracking_events::Column::RatedAt.gte(start))
        .filter(mood_tracking_events::Column::RatedAt.lt(end))
        .order_by_asc(mood_tracking_events::Column::Id)
        .all(db)
        .await?
    {
        if let Some(p) = parameters.get(&e.mood_tracking_parameter_id) {
            moods.entry(e.rated_at.0.date()).or_default().push(mood_event(e, p));
        }
    }

    let journal_ids: Vec<Id> = journals::Entity::find()
        .filter(journals::Column::VaultId.eq(vault_id))
        .all(db)
        .await?
        .into_iter()
        .map(|j| j.id)
        .collect();
    let rows = if journal_ids.is_empty() {
        Vec::new()
    } else {
        posts::Entity::find()
            .filter(posts::Column::JournalId.is_in(journal_ids))
            .filter(posts::Column::WrittenAt.gte(start))
            .filter(posts::Column::WrittenAt.lt(end))
            .order_by_asc(posts::Column::Id)
            .all(db)
            .await?
    };
    let mut posts: HashMap<NaiveDate, Vec<PostSummary>> = HashMap::new();
    for p in PostSummary::load_many(db, rows).await? {
        posts.entry(p.written_at).or_default().push(p);
    }

    let today = user_today(user);
    let utc_today = Utc::now().date_naive();
    Ok(days
        .into_iter()
        .map(|(date, is_in_month)| {
            let mut seen = HashSet::new();
            let important_dates = dates
                .dates
                .iter()
                .filter(|d| d.month == Some(date.month() as i32) && d.day == Some(date.day() as i32))
                .filter(|d| seen.insert(d.contact_id))
                .filter_map(|d| dates.view(d, utc_today))
                .collect();
            CalendarDay {
                date,
                is_today: date == today,
                is_in_month,
                important_dates,
                mood_tracking_events: moods.remove(&date).unwrap_or_default(),
                posts: posts.remove(&date).unwrap_or_default(),
            }
        })
        .collect())
}

fn check_year_month(v: &mut Validator, year: i64, month: i64) {
    v.between("year", Some(year), 1, 9999);
    v.between("month", Some(month), 1, 12);
}

// ---------------------------------------------------------------- reports

/// Groups `addresses` (by id) on the case-insensitive value of `place`:
/// the first stored spelling, and the number of live contacts with an
/// address in the group.
fn places(
    addresses: &[addresses::Model],
    place: impl Fn(&addresses::Model) -> Option<&String>,
    residents: &HashMap<Id, Vec<Uuid>>,
) -> Vec<(String, i64)> {
    let mut groups: Vec<(String, String, HashSet<Uuid>)> = Vec::new();
    for a in addresses {
        let Some(name) = place(a) else { continue };
        let key = name.to_lowercase();
        let index = match groups.iter().position(|g| g.0 == key) {
            Some(i) => i,
            None => {
                groups.push((key, name.clone(), HashSet::new()));
                groups.len() - 1
            }
        };
        groups[index].2.extend(residents.get(&a.id).into_iter().flatten().copied());
    }
    groups.into_iter().map(|(_, name, people)| (name, people.len() as i64)).collect()
}

/// The vault's addresses (by id) and, for each, its live contacts.
async fn vault_addresses<C: ConnectionTrait>(
    db: &C,
    vault_id: Uuid,
) -> ApiResult<(Vec<addresses::Model>, HashMap<Id, Vec<Uuid>>, HashMap<Uuid, contacts::Model>)> {
    let addresses = addresses::Entity::find()
        .filter(addresses::Column::VaultId.eq(vault_id))
        .order_by_asc(addresses::Column::Id)
        .all(db)
        .await?;
    let mut links = rows_in::<contact_address::Entity, _, _>(
        db,
        contact_address::Column::AddressId,
        addresses.iter().map(|a| a.id).collect(),
    )
    .await?;
    links.sort_by_key(|l| (l.address_id, l.contact_id));
    let contacts = contacts_in(db, vault_id, links.iter().map(|l| l.contact_id).collect()).await?;
    let mut residents: HashMap<Id, Vec<Uuid>> = HashMap::new();
    for l in links.into_iter().filter(|l| contacts.contains_key(&l.contact_id)) {
        residents.entry(l.address_id).or_default().push(l.contact_id);
    }
    Ok((addresses, residents, contacts))
}

/// `ReportCitiesShowViewHelper` / `ReportCountriesShowViewHelper`: the
/// addresses whose `place` is `name` (case-insensitive), with their contacts.
async fn place_report(
    state: &AppState,
    vault_id: Uuid,
    field: &str,
    name: Option<String>,
    place: impl Fn(&addresses::Model) -> Option<&String>,
) -> ApiResult<AddressPlaceReport> {
    let name = clean(name);
    let mut v = Validator::new();
    if v.required(field, &name) {
        v.max_len(field, name.as_deref(), 255);
    }
    v.finish()?;
    let name = name.unwrap_or_default();
    let key = name.to_lowercase();
    let db = &state.db;
    let (addresses, residents, contacts) = vault_addresses(db, vault_id).await?;
    let matching: Vec<&addresses::Model> =
        addresses.iter().filter(|a| place(a).is_some_and(|p| p.to_lowercase() == key)).collect();
    let types = address_types_of(db, &matching).await?;
    let people: Vec<contacts::Model> = matching
        .iter()
        .flat_map(|a| residents.get(&a.id).into_iter().flatten())
        .filter_map(|c| contacts.get(c).cloned())
        .collect();
    let cards = cards_by_id(db, people).await?;
    let addresses = matching
        .into_iter()
        .map(|a| {
            let view = address_view(a, &types);
            AddressPlaceReportAddresse {
                id: view.id,
                vault_id: view.vault_id,
                address_type: view.address_type,
                line_1: view.line_1,
                line_2: view.line_2,
                city: view.city,
                province: view.province,
                postal_code: view.postal_code,
                country: view.country,
                latitude: view.latitude,
                longitude: view.longitude,
                created_at: view.created_at,
                updated_at: view.updated_at,
                contacts: residents
                    .get(&a.id)
                    .into_iter()
                    .flatten()
                    .filter_map(|c| cards.get(c))
                    .map(copy_card)
                    .collect(),
            }
        })
        .collect();
    let lang = crate::i18n::current().split(['-', '_']).next().unwrap_or("en").to_lowercase();
    let wikipedia = crate::wikipedia::get_information(state.config.wikipedia_url.as_deref(), &lang, &name).await;
    Ok(AddressPlaceReport { name, addresses, wikipedia })
}

