// ---------------------------------------------------------------- handlers

#[utoipa::path(
    get,
    path = "/vaults/{vault_id}/dashboard",
    operation_id = "getVaultDashboard",
    tag = "Vaults",
    summary = "Everything the vault dashboard shows (aggregate)",
    params(("vault_id" = uuid::Uuid, Path)),
    responses((status = 200, description = "The dashboard data.", body = VaultDashboard), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`).")),
    extensions(("x-permission" = json!("vault:view")), ("x-inventory" = json!(["R015"])), ("x-services" = json!([])))
)]
pub async fn get_vault_dashboard(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path(vault_id): Path<Uuid>,
) -> ApiResult<Json<VaultDashboard>> {
    let access = access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::View).await?;
    let db = &state.db;
    let user_contact = contacts::Entity::find_by_id(access.membership.contact_id)
        .one(db)
        .await?
        .ok_or_else(|| ApiError::internal("the user has no contact in the vault"))?;

    let favorite_ids: Vec<Uuid> = contact_vault_user::Entity::find()
        .filter(contact_vault_user::Column::UserId.eq(id.user.id))
        .filter(contact_vault_user::Column::VaultId.eq(vault_id))
        .filter(contact_vault_user::Column::IsFavorite.eq(true))
        .all(db)
        .await?
        .into_iter()
        .map(|f| f.contact_id)
        .collect();
    let mut favorites: Vec<contacts::Model> = contacts_in(db, vault_id, favorite_ids).await?.into_values().collect();
    favorites.sort_by_key(|c| c.id);

    let last_updated = contacts::Entity::live()
        .filter(contacts::Column::VaultId.eq(vault_id))
        .order_by_with_nulls(contacts::Column::LastUpdatedAt, Order::Desc, NullOrdering::Last)
        .order_by_asc(contacts::Column::Id)
        .limit(5)
        .all(db)
        .await?;

    let now = now();
    // `$currentDate->second = 0` then `addDays(30)`.
    let in_30_days = now.with_second(0).unwrap_or(now) + Duration::days(30);
    let upcoming =
        scheduled_reminders(db, vault_id, contact_reminder_scheduled::Column::ScheduledAt.lte(Timestamp(in_30_days)))
            .await?;

    let contacts = vault_contacts(db, vault_id).await?;
    let due_tasks = open_tasks(db, contacts.keys().copied().collect(), Some(now + Duration::days(30)))
        .await?
        .into_iter()
        .filter_map(|t| {
            let c = contacts.get(&t.contact_id)?;
            Some(vault_task(t, c, now))
        })
        .collect();

    let mut parameters: Vec<mood_tracking_parameters::Model> =
        mood_parameters(db, vault_id).await?.into_values().collect();
    parameters.sort_by_key(|p| (p.position, p.id));

    Ok(Json(VaultDashboard {
        default_activity_tab: access.vault.default_activity_tab.clone(),
        favorites: favorites.into_iter().map(Into::into).collect(),
        last_updated_contacts: last_updated.into_iter().map(Into::into).collect(),
        upcoming_reminders: one_per_reminder(upcoming),
        due_tasks,
        mood_tracking_parameters: parameters.iter().map(mood_parameter).collect(),
        current_date: user_today(&id.user),
        life_events: life_events_module(
            &state,
            &ModuleContext { user: id.user.clone(), vault: access.vault.clone(), contact: user_contact.clone() },
        )
        .await?,
        life_metrics: life_metrics_of(db, vault_id, user_contact.id, current_year()).await?,
        user_contact: user_contact.into(),
    }))
}

