pub async fn get_vault_address_report(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path(vault_id): Path<Uuid>,
) -> ApiResult<Json<AddressReport>> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::View).await?;
    let (addresses, residents, _) = vault_addresses(&state.db, vault_id).await?;
    // F14: a place counts the contacts of all its addresses.
    let cities = places(&addresses, |a| a.city.as_ref(), &residents)
        .into_iter()
        .map(|(city, contacts_count)| AddressReportCity { city, contacts_count })
        .collect();
    let countries = places(&addresses, |a| a.country.as_ref(), &residents)
        .into_iter()
        .map(|(country, contacts_count)| AddressReportCountry { country, contacts_count })
        .collect();
    Ok(Json(AddressReport { cities, countries }))
}

