#[utoipa::path(
    get,
    path = "/vaults/{vault_id}/reports/mood-tracking-events",
    operation_id = "getVaultMoodTrackingReport",
    tag = "Vaults",
    summary = "The user's mood for every day of a year",
    params(("vault_id" = uuid::Uuid, Path), GetVaultMoodTrackingReportQuery),
    responses((status = 200, description = "12 months of days.", body = MoodTrackingReport), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`)."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("vault:view")), ("x-inventory" = json!(["R030"])), ("x-services" = json!([])))
)]
pub async fn get_vault_mood_tracking_report(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path(vault_id): Path<Uuid>,
    Query(query): Query<GetVaultMoodTrackingReportQuery>,
) -> ApiResult<Json<MoodTrackingReport>> {
    let access = access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::View).await?;
    let year = year_param(query.year)?;
    let db = &state.db;
    let first = NaiveDate::from_ymd_opt(year, 1, 1).ok_or_else(ApiError::not_found)?;
    let next = NaiveDate::from_ymd_opt(year + 1, 1, 1).ok_or_else(ApiError::not_found)?;
    let parameters = mood_parameters(db, vault_id).await?;
    // The latest event of each day (by `rated_at`, then id) wins.
    let mut latest: HashMap<NaiveDate, MoodTrackingReportMonthDayMoodTrackingEvent> = HashMap::new();
    for e in mood_tracking_events::Entity::find()
        .filter(mood_tracking_events::Column::ContactId.eq(access.membership.contact_id))
        .filter(mood_tracking_events::Column::RatedAt.gte(midnight(first)))
        .filter(mood_tracking_events::Column::RatedAt.lt(midnight(next)))
        .order_by_asc(mood_tracking_events::Column::RatedAt)
        .order_by_asc(mood_tracking_events::Column::Id)
        .all(db)
        .await?
    {
        let Some(p) = parameters.get(&e.mood_tracking_parameter_id) else { continue };
        latest.insert(
            e.rated_at.0.date(),
            MoodTrackingReportMonthDayMoodTrackingEvent {
                id: e.id,
                mood_tracking_parameter_id: e.mood_tracking_parameter_id,
                hex_color: p.hex_color.clone(),
            },
        );
    }
    // F14: every day of the month, the last one included.
    let months = (1..=12u32)
        .map(|month| MoodTrackingReportMonth {
            month: i64::from(month),
            days: (1..=last_day_of_month(year, month).day())
                .map(|day| MoodTrackingReportMonthDay {
                    day: i64::from(day),
                    mood_tracking_event: NaiveDate::from_ymd_opt(year, month, day).and_then(|d| latest.remove(&d)),
                })
                .collect(),
        })
        .collect();
    Ok(Json(MoodTrackingReport { year: i64::from(year), months }))
}

#[utoipa::path(
    get,
    path = "/vaults/{vault_id}/reports/important-dates",
    operation_id = "getVaultImportantDateReport",
    tag = "Vaults",
    summary = "Important dates of the next 12 months, by month",
    params(("vault_id" = uuid::Uuid, Path)),
    responses((status = 200, description = "12 months, in order.", body = ImportantDateReport), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`).")),
    extensions(("x-permission" = json!("vault:view")), ("x-inventory" = json!(["R031"])), ("x-services" = json!([])))
)]
pub async fn get_vault_important_date_report(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path(vault_id): Path<Uuid>,
) -> ApiResult<Json<ImportantDateReport>> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::View).await?;
    let mut dates = VaultDates::load(&state.db, vault_id, |d| d.month.is_some()).await?;
    // `orderBy('month')->orderBy('day')`, no day first as MySQL sorts nulls.
    dates.dates.sort_by_key(|d| (d.month, d.day, d.id));
    let today = Utc::now().date_naive();
    let months = (0..12)
        .map(|offset| {
            let (year, month) = month_after(today, offset);
            ImportantDateReportMonth {
                year: i64::from(year),
                month: i64::from(month),
                important_dates: dates
                    .dates
                    .iter()
                    .filter(|d| d.month == Some(month as i32))
                    .filter_map(|d| dates.view(d, today))
                    .map(Into::into)
                    .collect(),
            }
        })
        .collect();
    Ok(Json(ImportantDateReport { months }))
}

