#[utoipa::path(
    get,
    path = "/vaults/{vault_id}/companies",
    operation_id = "listVaultCompanies",
    tag = "Vaults",
    summary = "List the vault's companies with their contacts, by name",
    params(("vault_id" = uuid::Uuid, Path)),
    responses((status = 200, description = "Companies sorted by name (locale collation).", body = CompanyList), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`).")),
    extensions(("x-permission" = json!("vault:view")), ("x-inventory" = json!(["R171", "R091"])), ("x-services" = json!([])))
)]
pub async fn list_vault_companies(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path(vault_id): Path<Uuid>,
) -> ApiResult<Json<CompanyList>> {
    access::vault(&state, &id, vault_id, crate::domains::base::VaultPermission::View).await?;
    let db = &state.db;
    let mut companies = companies::Entity::find()
        .filter(companies::Column::VaultId.eq(vault_id))
        .order_by_asc(companies::Column::Id)
        .all(db)
        .await?;
    crate::text::sort_by_collator(&mut companies, |c| c.name.clone());
    let mut staff: HashMap<Id, Vec<contacts::Model>> = HashMap::new();
    if !companies.is_empty() {
        for c in contacts::Entity::live()
            .filter(contacts::Column::CompanyId.is_in(companies.iter().map(|c| c.id).collect::<Vec<_>>()))
            .order_by_asc(contacts::Column::Id)
            .all(db)
            .await?
        {
            if let Some(company_id) = c.company_id {
                staff.entry(company_id).or_default().push(c);
            }
        }
    }
    let data = companies
        .into_iter()
        .map(|c| CompanyListDataItem {
            contacts: staff.remove(&c.id).unwrap_or_default().into_iter().map(Into::into).collect(),
            id: c.id,
            vault_id: c.vault_id,
            name: c.name,
            r#type: c.r#type,
            created_at: ts(c.created_at),
            updated_at: ts(c.updated_at),
        })
        .collect();
    Ok(Json(CompanyList { data }))
}

